    location /.well-known/acme-challenge/ {
        alias /var/www/acme-challenge/.well-known/acme-challenge/;
        auth_basic off;
    }

{{/unless}}
{{{renderAdditionalRoutes additionalRoutes id accessList rateLimitEnabled rateLimitBurst connectionsPerIp}}}
{{#if pagesRouteIncludePath}}
    include {{pagesRouteIncludePath}};
    add_header X-Content-Type-Options nosniff always;
    add_header Referrer-Policy same-origin always;
{{#if pagesFallbackUrl}}
    error_page 404 =302 {{pagesFallbackUrl}};
{{else}}
    error_page 404 = @gateway_pages_not_found_{{id}};
{{/if}}
    location ~ /\. { deny all; }

    location = /_gateway/pages/config.js {
{{#if accessList}}
{{#each accessList.ipRules}}
        {{sanitize this.type}} {{sanitize this.value}};
{{/each}}
{{#if accessListHasIpRules}}
        deny all;
{{/if}}
{{#if accessList.basicAuthEnabled}}
        auth_basic "Restricted Access";
        auth_basic_user_file /etc/nginx/gateway/htpasswd/access-list-{{accessList.id}};
{{/if}}

{{/if}}
{{#if rateLimitEnabled}}
        limit_req_status 429;
        limit_req zone=ratelimit_{{id}} burst={{rateLimitBurst}} nodelay;
        limit_conn_status 429;
        limit_conn connlimit_{{id}} {{connectionsPerIp}};
{{/if}}
        limit_except GET HEAD { deny all; }
        alias $gateway_pages_runtime_config_path;
        default_type application/javascript;
        add_header Cache-Control "no-store" always;
{{#each customHeaders}}
        add_header {{sanitize this.name}} "{{sanitize this.value}}" always;
{{/each}}
    }

{{/if}}
    location / {
{{#if accessList}}
{{#each accessList.ipRules}}
        {{sanitize this.type}} {{sanitize this.value}};
{{/each}}
{{#if accessListHasIpRules}}
        deny all;
{{/if}}
{{#if accessList.basicAuthEnabled}}
        auth_basic "Restricted Access";
        auth_basic_user_file /etc/nginx/gateway/htpasswd/access-list-{{accessList.id}};
{{/if}}

{{/if}}
{{#if rateLimitEnabled}}
        limit_req_status 429;
        limit_req zone=ratelimit_{{id}} burst={{rateLimitBurst}} nodelay;
        limit_conn_status 429;
        limit_conn connlimit_{{id}} {{connectionsPerIp}};
{{/if}}
{{#if cacheEnabled}}
{{#if pagesRouteIncludePath}}
        expires {{cacheMaxAge}}s;
        add_header Cache-Control "public, max-age={{cacheMaxAge}}" always;
{{else}}
        proxy_cache cache_{{id}};
        proxy_cache_valid 200 301 302 {{cacheMaxAge}}s;
        proxy_cache_use_stale error timeout updating http_500 http_502 http_503 http_504;
        proxy_cache_background_update on;
        add_header X-Cache-Status $upstream_cache_status;
{{/if}}
{{/if}}
{{#if pagesRouteIncludePath}}
        limit_except GET HEAD { deny all; }
        sub_filter_once on;
        sub_filter '</head>' '<script src="/_gateway/pages/config.js"></script></head>';
{{#if pagesSpaFallback}}
        try_files $uri $uri/ /index.html;
{{else}}
        try_files $uri $uri/ =404;
{{/if}}
{{else}}
{{#if secureLinkUpstream}}
        # gateway-managed-secure-link-upstream {{id}}
{{/if}}
{{#if registryAuthRealm}}
        proxy_hide_header WWW-Authenticate;
        add_header WWW-Authenticate ${{registryAuthVariableName}} always;
{{/if}}
        proxy_pass {{upstream}};

        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Forwarded-Host $host;
        proxy_set_header X-Forwarded-Port $server_port;
{{#if secureLinkUpstream}}
{{#unless websocketSupport}}
        proxy_http_version 1.1;
        proxy_set_header Connection "";
{{/unless}}
{{/if}}

        proxy_connect_timeout 60s;
        proxy_send_timeout {{#if websocketSupport}}2h{{else}}{{#if secureLinkUpstream}}2h{{else}}60s{{/if}}{{/if}};
        proxy_read_timeout {{#if websocketSupport}}2h{{else}}{{#if secureLinkUpstream}}2h{{else}}60s{{/if}}{{/if}};

{{#if websocketSupport}}
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";

{{/if}}
{{/if}}
{{#each customHeaders}}
{{#if ../pagesRouteIncludePath}}
        add_header {{sanitize this.name}} "{{sanitize this.value}}" always;
{{else}}
        proxy_set_header {{sanitize this.name}} "{{sanitize this.value}}";
{{/if}}
{{/each}}
{{#each customRewrites}}
        rewrite {{sanitizeRewrite this.source}} {{sanitizeRewrite this.destination}} {{#if (eq this.type "permanent")}}permanent{{else}}redirect{{/if}};
{{/each}}
    }

{{#if pagesRouteIncludePath}}
{{#unless pagesFallbackUrl}}
    location @gateway_pages_not_found_{{id}} {
        default_type text/html;
        return 404 '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="color-scheme" content="light dark"><title>Page not found</title><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px;background:#fff;color:#09090b;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{width:100%;max-width:560px;text-align:center}.status{color:#71717a;font-size:12px;font-weight:600;letter-spacing:.12em;text-transform:uppercase}h1{margin:16px 0 0;font-size:clamp(40px,8vw,64px);line-height:1.05;font-weight:700;letter-spacing:-.04em}p.message{margin:20px auto 0;max-width:440px;color:#71717a;font-size:15px;line-height:1.6}.footer{margin-top:48px;color:#71717a;font-size:12px}.footer a{color:inherit;text-decoration:none}.footer a:hover{text-decoration:underline}@media(prefers-color-scheme:dark){body{background:#09090b;color:#fafafa}.status,p.message,.footer{color:#a1a1aa}.footer a{color:#fafafa}}</style></head><body><main><section><div class="status">Error 404</div><h1>Page not found</h1><p class="message">The requested host or page is not available.</p></section><div class="footer">Powered by <a href="https://thesquarelabs.com" rel="noopener noreferrer">Square Labs</a></div></main></body></html>';
    }
